colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
grid=[[0]*30 for _ in range(30)]
starts=[1,8,15,22]
# tiles 5x5: border 4 and 3x3 inner color
for i,y in enumerate(starts):
 for j,x in enumerate(starts):
  for dy in range(5):
   for dx in range(5):
    grid[y+dy][x+dx]=colors[i][j] if 1<=dy<=3 and 1<=dx<=3 else 4
# partial fifth column/row tile fragments: left edge of border at col 29 / row 29
for y in starts:
 grid[y][29]=4; grid[y+1][29]=4; grid[y+2][29]=4; grid[y+3][29]=4; grid[y+4][29]=4
for x in starts:
 grid[29][x:x+5]=[4]*5
# connect horizontal equal-color cells across gaps, as a shape-width bridge
for i,row in enumerate(colors):
 for j in range(4):
  for k in range(j+1,4):
   if row[j]==row[k]:
    # for each pair, fill all separators between columns j and k
    for between in range(j,k):
     for dy in range(1,4):
      for x in range(starts[between]+5, starts[between+1]):
       grid[starts[i]+dy][x]=row[j]
    break
# vertical connections analogous
for j in range(4):
 col=[colors[i][j] for i in range(4)]
 for i in range(4):
  for k in range(i+1,4):
   if col[i]==col[k]:
    for between in range(i,k):
     for dx in range(1,4):
      for y in range(starts[between]+5, starts[between+1]):
       grid[y][starts[j]+dx]=col[i]
    break
import json
print(json.dumps(grid))

